    ones = pd.Series(1, index=c.static.index)
    if c.name in n.one_port_components:
        return ones
    elif c.name in n.passive_branch_components:
        return -ones if port == 0 else ones
    elif c.name == "Link":
        if port == 0:
            return -ones
        key = c._port_coefficient_attr(port)
