    unflatten_snapshots,
    uses_flat_snapshots,
)
from pypsa.constants import RE_PORTS

if TYPE_CHECKING:
    from linopy import Model, Variable

    from pypsa import Network


def _snapshots_parameter(sns: pd.Index, flat: bool) -> pd.Index | xr.DataArray:
    """Return the snapshots stored in the model parameters."""
    if not flat:
        return sns
    return xr.DataArray(
        flat_snapshot_index(sns), coords=flat_snapshot_coords(sns), dims="snapshot"
    )


def _model_uses_flat_snapshots(m: Model) -> bool:
    """Whether model `m` uses flat `(period, timestep)` snapshot labels."""
    if "snapshots" not in m.parameters:
        return False
    snapshots = m.parameters.snapshots
    return "period" in snapshots.coords and not isinstance(
        snapshots.indexes.get("snapshot"), pd.MultiIndex
    )


def _model_snapshots(n: Network) -> pd.Index:
    """Return the snapshots of the model of `n` in the representation of `n`."""
    return unflatten_snapshots(n.model.parameters.snapshots).to_index()


def _model_snapshot_context(n: Network) -> contextlib.AbstractContextManager:
    """Make component data of `n` use the snapshot representation of its model."""
    return flat_snapshots_context(n, _model_uses_flat_snapshots(n.model))


def _to_model(n: Network, obj: Any) -> Any:
    """Convert a snapshot-indexed object to the snapshot representation in use."""
    return flatten_snapshots(obj) if uses_flat_snapshots(n) else obj


def _snapshot_coords(n: Network, sns: pd.Index) -> xr.Coordinates | dict[str, Any]:
    """Return coordinates for `sns` in the snapshot representation in use."""
    if isinstance(sns, pd.MultiIndex):
        if uses_flat_snapshots(n):
            return flat_snapshot_coords(sns)
        return xr.Coordinates.from_pandas_multiindex(sns, "snapshot")
    return {"snapshot": sns}


def _sel_snapshots(da: xr.DataArray, sns: pd.Index) -> xr.DataArray:
    """Select `sns` from `da` if it has a snapshot dimension."""
    return da.sel(snapshot=sns) if "snapshot" in da.dims else da


def _period_any(da: xr.DataArray, period: Any) -> xr.DataArray:
    """Whether `da` is True at any snapshot of investment period `period`."""
    return da.isel(snapshot=da.coords["period"].values == period).any("snapshot")


def _period_start_mask(n: Network, sns: pd.Index) -> xr.DataArray:
    """Mark the first snapshot of each investment period."""
    is_start = zeros(len(sns), dtype=bool)
    is_start[0] = True
    if isinstance(sns, pd.MultiIndex) and "period" in sns.names:
        periods = sns.get_level_values("period").to_numpy()
        is_start[1:] = periods[1:] != periods[:-1]
    return _to_model(n, xr.DataArray(is_start, coords=[sns]))


def _roll_within_periods(v: Variable) -> Variable:
    """Cyclically roll ``v`` by one snapshot within each investment period."""
    sns = v.indexes["snapshot"]
    positions = pd.Series(range(len(sns)))
    roll_index = positions.groupby(v.coords["period"].values).transform(
        lambda s: roll(s, 1)
    )
    rolled = v.isel(snapshot=roll_index.to_numpy())
    if isinstance(sns, pd.MultiIndex):
        coords = xr.Coordinates.from_pandas_multiindex(sns, "snapshot")
    else:
        coords = {k: v.coords[k] for k in ("snapshot", "period", "timestep")}
    return rolled.assign_coords(coords)

