def _is_v1() -> bool:
    return ln.options["semantics"] == "v1"


def _add_outer(expr: Any, other: Any) -> Any:
    """Add ``other`` to ``expr``, aligning the labels of both by an outer join."""
    if not _is_v1() or isinstance(other, int | float):
        return expr + other
    if isinstance(other, pd.Series) and other.empty:
        return expr.to_linexpr() if isinstance(expr, Variable) else expr
    return expr.add(other, join="outer")


def _groups_first(expr: LinearExpression) -> LinearExpression:
    """Order the dimensions of ``expr`` as groups, names and then time."""
    time_dims = ("snapshot", "period")
    dims = [d for d in expr.coord_dims if d not in (*time_dims, "name")]
    dims += [d for d in ("name", *time_dims) if d in expr.coord_dims]
    if tuple(dims) == tuple(expr.coord_dims):
        return expr
    ds = expr.data
    # xarray orders the dimensions of a dataset by its coordinates
    leading = [k for k, v in ds.coords.items() if set(v.dims) & set(dims[:1])]
    ds = xr.merge(
        [ds.coords.to_dataset()[leading], ds], compat="override", join="exact"
    )
    return LinearExpression(ds.transpose(*dims, ...), expr.model)


def _group_levels(expr: LinearExpression) -> list[str]:
    """Names of the level coordinates along the flat ``group`` dimension."""
    if "group" not in expr.dims:
        return []
    return [k for k, v in expr.coords.items() if k != "group" and v.dims == ("group",)]


def _group_index(expr: LinearExpression) -> pd.MultiIndex:
    """Return the labels of the flat ``group`` dimension as MultiIndex."""
    levels = _group_levels(expr)
    return pd.MultiIndex.from_arrays(
        [expr.coords[level].values for level in levels], names=levels
    )


def _with_group_labels(
    expr: LinearExpression, index: pd.MultiIndex
) -> LinearExpression:
    """Label the ``group`` dimension of ``expr`` by ``index``.

    A single level becomes the dimension itself. Several levels are kept as a flat
    ``group`` dimension labelled by tuples with one coordinate per level, since
    linopy's v1 semantics do not support a MultiIndex.
    """
    expr = expr.drop_vars(_group_levels(expr))
    if index.nlevels == 1:
        level = index.names[0]
        values = index.get_level_values(0)
        return expr.rename(group=level).assign_coords({level: values})
    labels = np.empty(len(index), dtype=object)
    labels[:] = list(index)
    coords: dict[str, Any] = {"group": labels}
    for i, level in enumerate(index.names):
        coords[level] = ("group", index.get_level_values(i))
    return expr.assign_coords(coords)


def _groupby_sum(
    expr: LinearExpression, grouping: pd.DataFrame, dim: str
) -> LinearExpression:
    """Sum ``expr`` along ``dim`` over the groups given by the ``grouping`` columns."""
    codes, uniques = pd.factorize(pd.MultiIndex.from_frame(grouping), sort=True)
    uniques = uniques.set_names([str(col) for col in grouping.columns])
    keep = codes >= 0
    if not keep.all():
        expr = expr.isel({dim: keep})
    grouper = pd.Series(
        codes[keep], index=expr.indexes[dim], name="group"
    ).rename_axis(dim)
    res = expr.groupby(grouper).sum()
    res = LinearExpression(res.data.transpose("group", ...), res.model)
    return _with_group_labels(res, uniques.take(res.indexes["group"]))


